const std = @import("std");

pub fn main() !void {
    var buf: [32]u8 = undefined;
    const line = try std.io.getStdIn().reader().readUntilDelimiterOrEof(&buf, '\n');
    if (line) |l| {
        const n = try std.fmt.parseInt(i64, l, 10);
        try std.io.getStdOut().writer().print("{d}\n", .{n * 2});
    }
}
